INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷84·晋少帝本纪·开运三年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/jiuwudaishi-084-946-august/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年八月，段落 jiu-wudaishi-205deb4a7860-p002041；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "dbf98f5f-500c-5272-94f5-172e997dd77e"}, {"title": "旧五代史·卷84·晋少帝本纪·开运三年七月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/jiuwudaishi-084-946-july/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年七月，段落 jiu-wudaishi-205deb4a7860-p002040；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "f3b48c08-49e4-5e00-afa8-1b7427780263"}, {"title": "旧五代史·卷84·晋少帝本纪·开运三年九月及赵延寿书信追述", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/jiuwudaishi-084-946-zhao-correspondence/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运三年九月及赵延寿书信追述，段落 jiu-wudaishi-205deb4a7860-p002042；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "c4802c9d-998b-5954-a3e2-b9d3cdf08d38"}, {"title": "旧五代史·卷99·汉高祖本纪·开运年间及白承福之死", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/jiuwudaishi-099-bai-chengfu-death/source.txt", "note": "《旧五代史》卷99·汉高祖本纪·开运年间及白承福之死，段落 jiu-wudaishi-205deb4a7860-p002425；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "bf9fe11b-db0c-51fd-bf1f-6910977a4ee3"}, {"title": "资治通鉴·卷285·开运三年·七月至八月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/tongjian-285-946-july-august/source.txt", "note": "《资治通鉴》卷285·开运三年·七月至八月及追述，段落 zizhi-tongjian-a63549944a71-p003386；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "9065cf5f-3381-582d-95c8-f62f9e013675"}, {"title": "新五代史·卷10·汉高祖本纪·白承福之死", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/xinwudaishi-010-bai-chengfu-death/source.txt", "note": "《新五代史》卷10·汉高祖本纪·白承福之死，段落 xin-wudaishi-b08f244b9241-p000347；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "5c5c684c-db90-5190-a781-6909e10bd8be"}, {"title": "新五代史·卷49·冯晖传·灵武市马与调任", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/xinwudaishi-049-feng-hui-horses/source.txt", "note": "《新五代史》卷49·冯晖传·灵武市马与调任，段落 xin-wudaishi-b08f244b9241-p001905；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "cc698825-873e-5f2e-b74f-5b6c5d684f3d"}, {"title": "新五代史·卷62·南唐世家·陈觉赴福州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/xinwudaishi-062-chen-jue-fuzhou/source.txt", "note": "《新五代史》卷62·南唐世家·陈觉赴福州，段落 xin-wudaishi-b08f244b9241-p003142；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "cef07fa0-ebe4-551b-8758-4a3b3e4794b6"}, {"title": "资治通鉴·卷285·开运三年·二月至六月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://git