INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "李彦韬（后晋宣徽使）", "aliases": ["李彥韜（後晉宣徽使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，早年曾侍奉阎宝，后来入石敬瑭帐下并留在太原侍奉石重贵。945年任宣徽北院使、暂代侍卫马步都虞候，与冯玉争桑维翰的权力。与早期曾名李彦韬的温韬分档，温韬在后唐明宗时已被赐死。生卒年本段未载。", "biography": null, "status": "draft", "id": "e4ac4a2d-843f-5686-98da-4b16e23f906d"}, {"name": "药元福", "aliases": ["藥元福"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州晋阳人，早年侍奉王檀及后唐，曾任深州刺史。945年任后晋马军右厢副排阵使，在白团卫村被围时主张逆风急击，与符彦卿、张彦泽、皇甫遇领骑兵出战。《宋史》还记他战后任威州刺史。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "9bbd6971-3005-5379-8428-512e90ae87d6"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "李殷", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟人，后晋义武节度使。946年六月受任北面行营步军都指挥使兼都排阵使。生卒年未载；与后周王殷分为不同主体。", "biography": null, "status": "draft", "id": "bfab47cb-1a5c-5497-982a-5bf911264b2b"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "白延遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋护圣指挥使。946年六月受命与王彦超带所属十营兵赴邢州。生卒年未载；不与皇甫遇等姓名相近将领混同。", "biography": null, "status": "draft", "id": "175ec9b6-d0c6-53ca-985e-f818a4d10d20"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "李仁达", "aliases": ["李仁達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光州人，曾任闽元从指挥使，多次在建州、福州之间投奔不同执政者。945年与陈继珣、黄仁讽发动福州政变，杀王继昌和吴成义，拥立僧卓岩明。后来又杀黄仁讽、陈继珣，将福州兵权集中到自己手中。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "97ca7dea-54b1-5a38-a747-3dc803037d55"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "赵行实", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：赵行实。", "biography": null, "status": "draft", "id": "1e3438d8-bb8d-5f3d-a0eb-1043359c15fc"}, {"name": "解里（946年契丹将）", "aliases": ["解里", "解裏"], "era": "五代十国", "birth_year": null, "death_year": 946, "description": "946年八月，李守贞报告在长城以北与契丹军交战，并斩杀酋帅解里。《旧五代史》写作解里相公。与945年狼山战记的谐里是否同一人尚未核实，暂按本次身份记录，不因近似译名合并。出生年未载。", "biography": null, "status": "draft", "id": "9ed4b263-b0a7-51f2-ba0d-e44b0d05d7fa"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "白承福", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吐谷浑酋长。941年四月辛巳，北京留守李德珫派牙校带领白承福入朝。原文没有说明他是否就是此前归附后晋的某支未具名部众首领。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "404c2172-d65b-534b-aed5-a6e9f5850b6a"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "白可久", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吐谷浑部落首领，史书记其地位次于白承福。带所属部众先逃往契丹，受任云州观察使；契丹试图借他招引白承福。具体逃归年月与生卒年未载。", "biography": null, "status": "draft", "id": "035af11f-c332-5cf0-bab5-26ddfc0c1b01"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "白铁匮", "aliases": ["白鐵匱"], "era": "五代十国", "birth_year": null, "death_year": 946, "description": "《旧五代史》晋少帝本纪记为吐谷浑大首领，刘知远在946年八月奏报与白承福、赫连海龙等一起被杀，其族亦遭杀害。处置与奏报日期须区分，生年未载。", "biography": null, "status": "draft", "id": "2b57a96b-2689-56d9-9022-bec23882d551"}, {"name": "赫连海龙", "aliases": ["赫連海龍"], "era": "五代十国", "birth_year": null, "death_year": 946, "description": "《旧五代史》晋少帝本纪记为吐谷浑大首领，946年八月刘知远奏报其与白承福、白铁匮等被杀并夷族。不同史书对这一处置的纪月有异说，生年未载。", "biography": null, "status": "draft", "id": "6f845158-8845-5085-9787-ce765fb0d0fb"}, {"name": "王义宗", "aliases": ["王義宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《旧五代史》汉高祖本纪记为吐谷浑别部首领，刘知远杀白承福等五族之后，命他统领其余部众。该书记在946年五月，其他史书把诛杀放在八月；不同纪月分别保留。生卒、所属别部具体名称未载。", "biography": null, "status": "draft", "id": "dea63583-99bd-5869-9054-98705684b536"}]'::jsonb)
